example_item.example_item_data:
clear classes
d = [tempdir(), 'nelson_help_setProperties/'];
mkdir(d);
filewrite([d, '/NelsonHelpColor.m'], ["classdef NelsonHelpColor < handle"; "  properties"; "    R = 0"; "    G = 0"; "    B = 0"; "  end"; "  methods"; "    function obj = NelsonHelpColor(varargin)"; "      setProperties(obj, nargin, varargin{:}, 'R', 'G', 'B');"; "    end"; "  end"; "end"]);
addpath(d);
c1 = NelsonHelpColor(255, 128)
c2 = NelsonHelpColor('B', 64)
delete(c1);
delete(c2)
